from pypdf import PdfReader
from pypdf.generic import ContentStream
import bisect
r=PdfReader('manuscript.pdf')
for name,obj in r.pages[4]['/Resources']['/XObject'].items():
 cs=ContentStream(obj.get_object(),r)
 lines=[]; path=[]; color=None
 for args,op in cs.operations:
  if op in [b'RG',b'G']:color=(op,[float(v) for v in args])
  if op==b'm':path=[tuple(float(v) for v in args)]
  elif op==b'l':path.append(tuple(float(v) for v in args))
  elif op in [b'S',b's',b'f',b'f*',b'B',b'B*',b'n']:
   if len(path)>20:lines.append((color,path))
   path=[]
 def sample(path):
  byx={round(2+(x-66.763636)*1022/(250.036364-66.763636)):y for x,y in path}
  xs=sorted(byx); ys=[byx[x] for x in xs]
  output=[]
  for x in range(2,1025):
   j=bisect.bisect_right(xs,x)-1
   if j>=len(xs)-1:output.append(ys[-1]);continue
   t=(x-xs[j])/(xs[j+1]-xs[j]);output.append(ys[j]*(1-t)+ys[j+1]*t)
  return output
 actual=sample(lines[0][1]); shownfit=sample(lines[1][1])
 avg=sum(actual)/len(actual);sst=sum((v-avg)**2 for v in actual)
 fitr2=1-sum((a-b)**2 for a,b in zip(actual,shownfit))/sst
 print(name,'R2 of displayed blue fit against reconstructed grey trace:',fitr2)
 for origin in [1,2]:
  grid=list(range(origin,origin+len(actual)))
  def fit(p):
   z=[x**p for x in grid];zb=sum(z)/len(z)
   A=sum((zi-zb)*(yi-avg) for zi,yi in zip(z,actual))/sum((zi-zb)**2 for zi in z)
   C=avg-A*zb
   return sum((yi-A*zi-C)**2 for zi,yi in zip(z,actual))
  err,p=min((fit(-j/1000),-j/1000) for j in range(1,2001))
  print('power fit starting index',origin,'R2',1-err/sst,'exponent',p)
